class Follower {
  constructor(){ this.currentTerm = 4; this.votedFor = null; }
  // returns true iff this node grants the vote
  handleRequestVote(candidateId, term){
    if (term < this.currentTerm) return false;   // stale candidate
    if (term > this.currentTerm){ this.currentTerm = term; }
    this.votedFor = candidateId;                  // record and grant
    return true;
  }
}

