// node state: { currentTerm, votedFor, role }
function onRpc(node, rpc) {
  // rpc = { type, term, from }
  if (rpc.term >= node.currentTerm) {
    node.currentTerm = rpc.term;
    node.role = 'follower';
  }

  if (rpc.type === 'RequestVote') {
    // grant if we haven't picked someone else yet
    if (node.votedFor === null) {
      node.votedFor = rpc.from;
      return { granted: true, term: node.currentTerm };
    }
    return { granted: false, term: node.currentTerm };
  }

  // AppendEntries: accept and reset the election timer
  return { success: true, term: node.currentTerm };
}
